<template>
  <PageContainer :title="portfolio?.name || '持仓管理'" description="维护真实持仓数量、成本和建仓信息">
    <template #actions><el-button @click="$router.push(`/portfolio/${id}/analysis`)">查看持仓分析</el-button><el-button @click="importVisible=true">导入 CSV</el-button><el-button type="primary" @click="openEditor()">添加持仓</el-button></template>
    <section class="data-table-card"><div class="toolbar"><strong>持仓明细</strong><span class="muted">{{ positions.length }} 只股票</span></div><div class="table-scroll-x"><el-table :data="positions" v-loading="loading" class="position-table" empty-text="暂无持仓"><el-table-column prop="symbol" label="代码" width="100"/><el-table-column prop="name" label="名称" width="140"/><el-table-column prop="quantity" label="持仓数量" width="120"/><el-table-column prop="available_quantity" label="可用数量" width="120"/><el-table-column label="成本价" width="120"><template #default="{row}">{{money(row.avg_cost)}}</template></el-table-column><el-table-column prop="opened_on" label="建仓日期" width="130"/><el-table-column prop="note" label="备注" min-width="180"/><el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><el-button size="small" @click="openEditor(row)">编辑</el-button><el-popconfirm title="确认删除该持仓？" @confirm="remove(row.id)"><template #reference><el-button size="small" type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table></div></section>
    <el-dialog v-model="editorVisible" :title="form.id ? '编辑持仓' : '添加持仓'" width="min(560px, 94vw)"><el-form label-position="top" class="edit-grid"><el-form-item label="股票代码"><el-input v-model="form.symbol" maxlength="6"/></el-form-item><el-form-item label="股票名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="持仓数量"><el-input-number v-model="form.quantity" :min="1" :step="100"/></el-form-item><el-form-item label="可用数量"><el-input-number v-model="form.available_quantity" :min="0" :max="form.quantity" :step="100"/></el-form-item><el-form-item label="成本价"><el-input-number v-model="form.avg_cost" :min="0.001" :precision="4"/></el-form-item><el-form-item label="建仓日期"><el-date-picker v-model="form.opened_on" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item class="full" label="备注"><el-input v-model="form.note" type="textarea" :rows="2" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="editorVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
    <el-dialog v-model="importVisible" title="导入真实持仓 CSV" width="min(720px, 94vw)"><el-alert title="先预览校验，确认后才写入持仓；必填列：股票代码、持仓数量、成本价" type="info" show-icon :closable="false"/><el-upload class="uploader" drag :auto-upload="false" :limit="1" accept=".csv,text/csv" :on-change="onFile"><div>点击或拖入 CSV 文件</div></el-upload><template v-if="preview"><el-descriptions :column="3" border><el-descriptions-item label="总行数">{{preview.total_rows||0}}</el-descriptions-item><el-descriptions-item label="有效">{{preview.valid_rows||0}}</el-descriptions-item><el-descriptions-item label="错误">{{preview.invalid_rows||0}}</el-descriptions-item></el-descriptions><el-table v-if="preview.errors?.length" :data="preview.errors" max-height="220"><el-table-column prop="row_number" label="行" width="70"/><el-table-column prop="field" label="字段" width="110"/><el-table-column prop="message" label="错误"/></el-table></template><template #footer><el-button @click="importVisible=false">取消</el-button><el-button :disabled="!file" :loading="previewing" @click="previewFile">预览校验</el-button><el-button type="primary" :disabled="!preview || (preview.invalid_rows||0)>0" :loading="saving" @click="confirmImport">确认导入</el-button></template></el-dialog>
  </PageContainer>
</template>

<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { useRoute } from 'vue-router';import { ElMessage,type UploadFile } from 'element-plus';import PageContainer from '@/components/common/PageContainer.vue';import {portfolioApi} from '@/api/portfolio';import {money} from '@/utils/format';import type{PositionImportPreview,RealPortfolio,RealPosition}from '@/types/portfolio'
const id=Number(useRoute().params.id),portfolio=ref<RealPortfolio>(),positions=ref<RealPosition[]>([]),loading=ref(false),saving=ref(false),editorVisible=ref(false),importVisible=ref(false),previewing=ref(false),file=ref<File>(),preview=ref<PositionImportPreview>()
const form=reactive({id:0,symbol:'',name:'',quantity:100,available_quantity:100,avg_cost:1,opened_on:'',note:'',version:0})
const load=async()=>{loading.value=true;try{[portfolio.value,positions.value]=await Promise.all([portfolioApi.get(id),portfolioApi.positions(id)])}finally{loading.value=false}}
const openEditor=(row?:RealPosition)=>{Object.assign(form,row?{...row,avg_cost:Number(row.avg_cost)}:{id:0,symbol:'',name:'',quantity:100,available_quantity:100,avg_cost:1,opened_on:'',note:'',version:0});editorVisible.value=true}
const save=async()=>{saving.value=true;try{const payload={...form};form.id?await portfolioApi.updatePosition(id,form.id,payload):await portfolioApi.addPosition(id,payload);ElMessage.success('持仓已保存');editorVisible.value=false;await load()}finally{saving.value=false}}
const remove=async(positionId:number)=>{await portfolioApi.removePosition(id,positionId);ElMessage.success('持仓已删除');await load()}
const onFile=(item:UploadFile)=>{file.value=item.raw;preview.value=undefined}
const previewFile=async()=>{if(!file.value)return;previewing.value=true;try{preview.value=await portfolioApi.previewImport(id,file.value,`web-${file.value.name}-${file.value.size}-${file.value.lastModified}`)}finally{previewing.value=false}}
const confirmImport=async()=>{if(!preview.value)return;saving.value=true;try{await portfolioApi.confirmImport(id,preview.value.task_id);ElMessage.success('CSV 持仓已导入');importVisible.value=false;await load()}finally{saving.value=false}}
onMounted(load)
</script>
<style scoped>.position-table{min-width:980px}.edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.full{grid-column:1/-1}.uploader{margin:16px 0}@media(max-width:600px){.edit-grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
